import{_ as e,o as t,c as r,a2 as a}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"插件","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/settings/plugins.md","filePath":"zh-CN/user-guide/settings/plugins.md","lastUpdated":1787497304000}'),n={name:"zh-CN/user-guide/settings/plugins.md"};function s(l,o,d,c,i,g){return t(),r("div",null,[...o[0]||(o[0]=[a('<h1 id="插件" tabindex="-1">插件 <a class="header-anchor" href="#插件" aria-label="Permalink to &quot;插件&quot;">​</a></h1><p>列出所有已安装的插件，页面头部的徽标显示当前加载的 Plugin SDK 版本——点击它可以直接打开<a href="./../../dev-guide/">开发手册</a>，这个版本号正是为了对照手册开发插件而准备的。</p><p>页面分成左右两栏：左边是已安装的插件，右边是选中插件的详情。两栏各自独立滚动，插件列表很长和配置表单很长互不牵扯。</p><p>如果没有安装任何插件，页面会显示一个空状态提示。</p><h2 id="插件列表" tabindex="-1">插件列表 <a class="header-anchor" href="#插件列表" aria-label="Permalink to &quot;插件列表&quot;">​</a></h2><p>每个已安装的插件占一行，显示名称，下方是它的版本号。点击某一行，右侧就会打开该插件。</p><p>列表按&quot;有什么可操作的&quot;排序：先是有自己配置项的插件，其次是有组件可以关闭的，最后是其余的；每一档内部按名称排列。</p><h2 id="选中的插件" tabindex="-1">选中的插件 <a class="header-anchor" href="#选中的插件" aria-label="Permalink to &quot;选中的插件&quot;">​</a></h2><p>右栏最上方是插件的图标、名称和<strong>总体功能简介</strong>。</p><p>再往下，如果插件暴露了自己的配置项(超出简单启用/禁用的范畴)，会出现<strong>详情</strong>和<strong>配置</strong>两个标签页。没有任何配置项的插件不会显示标签栏——整栏就是它的详情。</p><h3 id="详情" tabindex="-1">详情 <a class="header-anchor" href="#详情" aria-label="Permalink to &quot;详情&quot;">​</a></h3><p>该插件注册的功能组件，按类型分组（搜索源、动态菜单提供者等）。每个可切换的组件都有自己的<strong>启用/禁用复选框</strong>；标记为必要项的组件会显示一个锁形图标，不能关闭。把鼠标悬停在组件旁边的 <strong>(!)</strong> 上，可以看到该组件的详细功能说明。</p><p>当某个分组（或整个插件）有 2 个及以上可切换组件时，标题旁会出现一个<strong>全选/全不选</strong>链接，点击即可一次性切换该范围内的所有复选框，不用逐个手动勾选。</p><h3 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to &quot;配置&quot;">​</a></h3><p>插件自己的设置项，直接在这里编辑，不再另开对话框。如果插件把设置分成了 2 组及以上，这里还会有一行属于它自己的标签页，每组一个。</p><p>按下<strong>确定</strong>之前，什么都不会写入。离开这个标签页——切回详情，或者选择另一个插件——会把这些字段回滚到已保存的值，这样你放弃掉的修改就不会在之后被误提交。</p><p>想看插件配置实际长什么样、能改什么(比如改一个触发关键词)，可以参考<a href="./../instant-answers.html">即时答案与关键词功能</a>。</p><h2 id="flow-launcher-插件生态支持" tabindex="-1">Flow Launcher 插件生态支持 <a class="header-anchor" href="#flow-launcher-插件生态支持" aria-label="Permalink to &quot;Flow Launcher 插件生态支持&quot;">​</a></h2><p>除了基于 <code>Lertaro.PluginSdk</code> 构建的原生 C# 插件之外，Lertaro 还通过内置的 Flow Launcher Bridge 提供了对庞大 Flow Launcher 社区插件生态的原生级兼容支持。</p><ul><li><strong>支持的插件类型</strong>：兼容 <strong>C# (.NET)</strong>、<strong>Python 3.12</strong>（支持根据 <code>requirements.txt</code> 自动在后台安装 <code>pip</code> 依赖）、<strong>Node.js v20 LTS</strong>（支持根据 <code>package.json</code> 自动在后台安装 <code>npm</code> 依赖）以及独立<strong>可执行程序</strong>（<code>.exe</code>）编写的 Flow Launcher 插件。</li><li><strong>在线社区市场安装与包管理 (<code>flow install</code> / <code>flow update</code> / <code>flow uninstall</code>)</strong>：在搜索框中输入 <code>flow install</code> 或 <code>flow install &lt;插件名/关键词&gt;</code> 即可检索 Flow.Launcher 官方在线社区插件库，回车即可全自动下载、解压并部署到 <code>FlowData\\Plugins\\</code>，并在后台静默安装所需的 Python/Node.js 运行环境与依赖包；输入 <code>flow update</code> 可检测并一键更新已安装的 Flow 插件；输入 <code>flow uninstall &lt;插件名&gt;</code> 可快速卸载插件并清理对应目录。亦可直接将第三方插件文件夹放入 <code>&lt;用户数据目录&gt;\\FlowData\\Plugins\\</code> 完成本地安装。</li><li><strong>纯净隔离运行环境</strong>：Python（<code>FlowData\\PythonEmbeded-{arch}</code>）与 Node.js（<code>FlowData\\NodeEmbeded-{arch}</code>）运行时完全隔离在 Lertaro 的数据目录中按需自动下载部署，不依赖也不污染系统的全局环境变量与 PATH。</li><li><strong>集中管理与独立开关</strong>：在<strong>设置 → 插件 → Flow Launcher Bridge</strong> 的<strong>配置</strong>标签页中，统一列出所有已加载的 Flow 插件子分组；每个插件顶部均设有专属的<strong>启用此插件</strong>开关，可单独开启或关闭该插件功能。</li><li><strong>自定义触发词与状态隔离</strong>：支持自定义修改每个 Flow 插件的专属<strong>触发词（ActionKeyword）</strong>，配置与启用状态集中存储于 <code>FlowData\\Settings\\Plugins.json</code>，不会污染插件内部配置，插件更新与重启后始终保持有效。</li><li><strong>原生内嵌配置与多语言</strong>：无缝支持基于 YAML/JSON 模板表单（<code>SettingsTemplate.yaml</code>/<code>.json</code>）及 C# WPF 自定义设置面板（<code>ISettingProvider</code>）的插件配置界面，自动融合应用主题并完整支持多语言 i18n 本地化。</li><li><strong>自定义交互式预览与 WebView2 排版美化</strong>：支持 Flow Launcher 插件返回的自定义交互式预览面板（如 MDict 词典释义、天气卡片、API 调试信息、网页预览等），选定结果即可在 QuickLook 预览面板中免额外按键平滑展开并即时切换；对于基于 WebView2/HTML 的富文本预览，Lertaro 会自动注入深浅色自适应主题样式、高对比度清晰字体（Segoe UI / 微软雅黑）及精致的半透明细滚动条。</li><li><strong>快捷搜索与调用</strong>：在搜索框中输入 <code>flow</code> 全局关键词即可列出已加载的全部 Flow 插件及其触发词与运行状态；直接输入各插件的触发词（如 <code>md</code>、<code>tr</code> 等）即可即时检索。</li></ul>',20)])])}const p=e(n,[["render",s]]);export{u as __pageData,p as default};
